WITH with_windows AS (SELECT id, page, duration_sec, PERCENT_RANK() OVER (PARTITION BY session_id ORDER BY duration_sec ASC NULLS LAST) duration_sec_percent_rank, SUM(duration_sec) OVER w_hist running_duration_sec, SUM(duration_sec) OVER w_recent running_duration_sec_2, AVG(duration_sec) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) duration_sec_avg_5 FROM web_events WINDOW w_hist AS (PARTITION BY event_type, session_id ORDER BY event_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_recent AS (PARTITION BY event_type ORDER BY event_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT id, page, duration_sec, duration_sec_percent_rank, running_duration_sec, running_duration_sec_2 FROM with_windows
